class WebSocketNetworkDiagCommands:
    """
    WebSocket Network Diagnostic Commands

    Handles ping, ARP, and service ping operations via WebSocket.
    Extracted from WebSocketCommands.
    """

    @staticmethod
    def ping_device():  # type: ignore[no-untyped-def]  # noqa: C901, PLR0912, PLR0915
        """
        Execute ping command on a network device via WebSocket.

        Follows the documented Mist API pattern:
        1. Connect to WebSocket
        2. Subscribe to device command channel
        3. Issue POST ping command
        4. Await results via WebSocket stream

        SECURITY: Uses authenticated WebSocket connection with session-based
        command demultiplexing for concurrent command safety.
        """
        logging.info("Starting WebSocket ping operation...")

        # Check for debug mode from command line args
        debug_mode = "--debug" in sys.argv or "-d" in sys.argv

        if debug_mode:
            logging.getLogger().setLevel(logging.DEBUG)
            print("[DEBUG] DEBUG MODE ENABLED")

        logging.info("Starting WebSocket ping operation...")
        logging.debug("ENTER: ping_device_websocket")

        try:
            # Interactive site and device selection
            site_id = PromptUtils.select_site_id_from_csv()
            if not site_id:
                print("! No site selected. Operation cancelled.")
                return

            if debug_mode:
                print(f"[DEBUG] Selected site_id = {site_id}")

            # Get device selection
            device_id = PromptUtils.select_device_id_from_inventory(site_id, device_type="all")
            if not device_id:
                print("! No device selected. Operation cancelled.")
                return

            if debug_mode:
                print(f"[DEBUG] Selected device_id = {device_id}")

            # Get ping target from user (default to 8.8.8.8)
            target_input = input("Enter the target hostname or IP address to ping (default: 8.8.8.8): ").strip()
            target_host = target_input if target_input else "8.8.8.8"

            # Validate target host
            if not ValidationUtils.validate_ping_target(target_host):
                print(f"! Invalid ping target: {target_host}")
                return

            if debug_mode:
                print(f"[DEBUG] Target host = {target_host}")

            # Get ping count (optional)
            ping_count_input = input("Enter number of ping packets (default: 4): ").strip()
            ping_count = 4
            if ping_count_input:
                try:
                    ping_count = int(ping_count_input)
                    if ping_count < 1 or ping_count > 100:
                        print("! Ping count must be between 1 and 100. Using default: 4")
                        ping_count = 4
                except ValueError:
                    print("! Invalid ping count. Using default: 4")
                    ping_count = 4

            if debug_mode:
                print(f"[DEBUG] Ping count = {ping_count}")

            print(f"\n-> Executing ping to {target_host} on device {device_id}...")
            print(f"-> Ping count: {ping_count}")
            print("-> Establishing WebSocket connection...")

            # Initialize WebSocket manager
            websocket_manager = WebSocketManager(apisession)

            if debug_mode:
                print("[DEBUG] WebSocketManager initialized")

            # Connect to WebSocket
            if not websocket_manager.connect():
                print("! Failed to establish WebSocket connection")
                return

            if debug_mode:
                print("[DEBUG] WebSocket connection established")

            # Subscribe to device command channel
            command_channel = f"/sites/{site_id}/devices/{device_id}/cmd"
            if not websocket_manager.subscribe_to_channel(command_channel):
                print("! Failed to subscribe to device command channel")
                websocket_manager.disconnect()
                return

            if debug_mode:
                print(f"[DEBUG] Subscribed to channel: {command_channel}")

            print("-> WebSocket connected and subscribed")

            # Wait a moment for subscription to be established
            time.sleep(1)

            # Issue ping command via REST API
            ping_payload = {"host": target_host, "count": ping_count}

            print("-> Issuing ping command...")
            logging.debug(f"Ping payload: {ping_payload}")

            if debug_mode:
                print(f"[DEBUG] Ping payload = {ping_payload}")

            # Get authentication details for direct HTTP request
            mist_host = getattr(apisession, "host", None) or os.getenv("MIST_HOST")
            mist_apitoken = getattr(apisession, "apitoken", None) or os.getenv("MIST_APITOKEN")

            if not mist_host or not mist_apitoken:
                print("! Mist host or API token not found in session or environment")
                websocket_manager.disconnect()
                return

            if debug_mode:
                print(f"[DEBUG] mist_host = {mist_host}")
                print(f"[DEBUG] API token length = {len(mist_apitoken) if mist_apitoken else 0}")

            # Make direct POST request to trigger ping
            ping_url = f"https://{mist_host}/api/v1/sites/{site_id}/devices/{device_id}/ping"
            headers = {"Authorization": f"Token {mist_apitoken}", "Content-Type": "application/json"}

            if debug_mode:
                print(f"[DEBUG] POST URL = {ping_url}")
                print("[DEBUG] Headers = {'Authorization': 'Token [REDACTED]', 'Content-Type': 'application/json'}")

            ping_response = requests.post(ping_url, headers=headers, json=ping_payload, timeout=30)

            if debug_mode:
                print(f"[DEBUG] HTTP Response Status = {ping_response.status_code}")
                print(f"[DEBUG] HTTP Response Body = {ping_response.text}")

            if ping_response.status_code != 200:
                print(f"! Failed to issue ping command: {ping_response.status_code}")
                print(f"! Response: {ping_response.text}")
                websocket_manager.disconnect()
                return

            # Extract session ID from response
            response_data = ping_response.json()
            session_id = response_data.get("session")
            if not session_id:
                print("! No session ID returned from ping command")
                websocket_manager.disconnect()
                return

            print(f"-> Ping command issued (session: {session_id[:8]}...)")
            print("-> Waiting for ping results...")

            if debug_mode:
                print(f"[DEBUG] Full session ID = {session_id}")
                print("[DEBUG] Starting to wait for WebSocket results...")

            # Wait for ping results via WebSocket
            ping_result = websocket_manager.wait_for_command_result(session_id, timeout_seconds=30)

            if debug_mode:
                print(f"[DEBUG] wait_for_command_result returned: {ping_result is not None}")
                if ping_result:
                    print(f"[DEBUG] Result keys: {list(ping_result.keys())}")

            if ping_result:
                print("\n" + "=" * 60)
                print("PING RESULTS:")
                print("=" * 60)

                # Display raw output (this is where ping results come according to documentation)
                raw_output = ping_result.get("raw", "")
                if raw_output:
                    print("RAW OUTPUT:")
                    print("-" * 40)
                    print(raw_output)

                # Display any other output fields that might be present
                output_fields = ping_result.get("Output", "")
                if output_fields and output_fields != raw_output:
                    print("\nOTHER OUTPUT:")
                    print("-" * 40)
                    print(output_fields)

                # Show all available fields for debugging
                available_fields = [key for key in ping_result.keys() if key not in ["raw", "Output", "session"]]
                if available_fields:
                    print(f"\nOTHER AVAILABLE FIELDS: {available_fields}")
                    for field in available_fields:
                        field_value = ping_result.get(field)
                        if field_value:
                            print(f"{field}: {field_value}")

                if not raw_output and not output_fields:
                    print("No output data received")
                    print(f"Available result keys: {list(ping_result.keys())}")

                print("=" * 60)

                # Log the successful operation
                logging.info(f"WebSocket ping completed successfully for {target_host}")

            else:
                print("! Timeout waiting for ping results")
                logging.warning("WebSocket ping operation timed out")

                if debug_mode:
                    print("[DEBUG] Checking WebSocket manager state...")
                    print(f"[DEBUG] Connected = {websocket_manager.connected}")
                    print(f"[DEBUG] Subscribed channels = {websocket_manager.subscribed_channels}")
                    with websocket_manager.results_lock:
                        print(f"[DEBUG] Pending results = {list(websocket_manager.command_results.keys())}")

        except Exception as ping_error:
            error_message = f"WebSocket ping operation failed: {ping_error}"
            print(f"! {error_message}")
            logging.error(error_message)

            if debug_mode:
                print("[DEBUG] Exception details:")
                import traceback

                traceback.print_exc()

            logging.debug("EXIT: ping_device_websocket - error")

        finally:
            # Always cleanup WebSocket connection
            try:
                websocket_manager_local = locals().get("websocket_manager")
                if websocket_manager_local is not None:
                    websocket_manager_local.disconnect()
                    print("-> WebSocket connection closed")

                    if debug_mode:
                        print("[DEBUG] WebSocket cleanup completed")
            except Exception as cleanup_error:
                logging.warning(f"WebSocket cleanup error: {cleanup_error}")

            logging.debug("EXIT: ping_device_websocket")

    @staticmethod
    def arp_device():  # type: ignore[no-untyped-def]  # noqa: C901, PLR0912, PLR0915
        """
        Execute ARP command on a network device via WebSocket.

        Follows the documented Mist API pattern for ARP commands:
        1. Subscribe to WebSocket channel
        2. POST ARP command
        3. Receive results via WebSocket stream with session-based demultiplexing

        SECURITY: Uses authenticated WebSocket connection with session-based
        command demultiplexing for concurrent command safety.
        """
        logging.info("Starting WebSocket ARP operation...")
        logging.debug("ENTER: arp_device_websocket")

        debug_mode = "--debug" in sys.argv or "-d" in sys.argv

        if debug_mode:
            print("[DEBUG] Starting ARP via WebSocket operation...")

        try:
            # Interactive site and device selection
            site_id = PromptUtils.select_site_id_from_csv()
            if not site_id:
                print("! No site selected. Operation cancelled.")
                return

            if debug_mode:
                print(f"[DEBUG] Selected site_id = {site_id}")

            # Get device selection
            device_id = PromptUtils.select_device_id_from_inventory(site_id, device_type="all")
            if not device_id:
                print("! No device selected. Operation cancelled.")
                return

            if debug_mode:
                print(f"[DEBUG] Selected device_id = {device_id}")

            # Get device details to check type and model for compatibility
            device_info = None
            try:
                rawdata = mistapi.api.v1.sites.devices.listSiteDevices(apisession, site_id, type="all").data
                device_info = next((device for device in rawdata if device.get("id") == device_id), None)

                if device_info:
                    device_type = device_info.get("type", "unknown")
                    device_model = device_info.get("model", "unknown")
                    device_name = device_info.get("name", f"Device {device_id[:8]}")

                    if debug_mode:
                        print(f"[DEBUG] Device type: {device_type}, model: {device_model}, name: {device_name}")

                    # Warn about device compatibility
                    if device_type == "switch":
                        print(f"!?  WARNING: Switch detected (Model: {device_model})")
                        print("   -> Switches may have limited WebSocket ARP support")
                        print("   -> Consider using SSH-based ARP commands instead")
                        print("   -> This operation may timeout or return limited results")

                        response = input("   -> Continue anyway? (y/N): ").strip().lower()
                        if response not in ["y", "yes"]:
                            print("! Operation cancelled by user")
                            return

                    elif device_type == "gateway":
                        print(f"!? Gateway detected (Model: {device_model})")
                        print("   -> Gateways have good WebSocket ARP support")
                        print("   -> Results may differ from Access Points")

                    elif device_type == "ap":
                        print(f"!? Access Point detected (Model: {device_model})")
                        print("   -> Access Points have full WebSocket ARP support")

                    else:
                        print(f"? Unknown device type: {device_type} (Model: {device_model})")
                        print("   -> Proceeding with standard ARP command")

            except Exception as device_check_error:
                logging.warning(f"Could not verify device compatibility: {device_check_error}")
                if debug_mode:
                    print(f"[DEBUG] Device check failed: {device_check_error}")
                print("   -> Proceeding with standard ARP command")

            print(f"\n-> Executing ARP command on device {device_id}...")
            print("-> Establishing WebSocket connection...")

            if debug_mode:
                print("[DEBUG] WebSocketManager initialized")

            # Initialize WebSocket manager
            websocket_manager = WebSocketManager(apisession)

            # Connect to WebSocket
            if not websocket_manager.connect():
                print("! Failed to establish WebSocket connection")
                return

            if debug_mode:
                print("[DEBUG] WebSocket connection established")

            # Subscribe to device command channel
            command_channel = f"/sites/{site_id}/devices/{device_id}/cmd"
            if not websocket_manager.subscribe_to_channel(command_channel):
                print("! Failed to subscribe to device command channel")
                websocket_manager.disconnect()
                return

            if debug_mode:
                print(f"[DEBUG] Subscribed to channel: {command_channel}")

            print("-> WebSocket connected and subscribed")

            # Wait a moment for subscription to be established
            time.sleep(1)

            print("-> Issuing ARP command...")

            # Get authentication details for direct HTTP request
            mist_host = getattr(apisession, "host", None) or os.getenv("MIST_HOST")
            mist_apitoken = getattr(apisession, "apitoken", None) or os.getenv("MIST_APITOKEN")

            if debug_mode:
                print(f"[DEBUG] mist_host = {mist_host}")
                print(f"[DEBUG] API token length = {len(mist_apitoken) if mist_apitoken else 'None'}")

            if not mist_host or not mist_apitoken:
                print("! Mist host or API token not found in session or environment")
                websocket_manager.disconnect()
                return

            # Make direct POST request to trigger ARP command
            arp_url = f"https://{mist_host}/api/v1/sites/{site_id}/devices/{device_id}/arp"
            headers = {"Authorization": f"Token {mist_apitoken}", "Content-Type": "application/json"}

            if debug_mode:
                print(f"[DEBUG] POST URL = {arp_url}")
                print("[DEBUG] Headers = {'Authorization': 'Token [REDACTED]', 'Content-Type': 'application/json'}")

            # ARP command typically doesn't need a payload body
            arp_response = requests.post(arp_url, headers=headers, json={}, timeout=30)

            if debug_mode:
                print(f"[DEBUG] HTTP Response Status = {arp_response.status_code}")
                print(f"[DEBUG] HTTP Response Body = {arp_response.text}")

            if arp_response.status_code != 200:
                print(f"! Failed to issue ARP command: {arp_response.status_code}")
                print(f"! Response: {arp_response.text}")
                websocket_manager.disconnect()
                return

            # Extract session ID from response
            response_data = arp_response.json()
            session_id = response_data.get("session")
            if not session_id:
                print("! No session ID returned from ARP command")
                websocket_manager.disconnect()
                return

            print(f"-> ARP command issued (session: {session_id[:8]}...)")
            print("-> Waiting for ARP results...")

            if debug_mode:
                print(f"[DEBUG] Full session ID = {session_id}")
                print("[DEBUG] Starting to wait for WebSocket results...")

            # Determine timeout based on device type
            if device_info:
                device_type = device_info.get("type", "unknown")
                if device_type == "switch":
                    # Switches often timeout, give them more time
                    timeout_seconds = 45
                    print("   -> Using extended timeout for switch (45 seconds)")
                elif device_type == "gateway":
                    # Gateways work but may be slower
                    timeout_seconds = 35
                    print("   -> Using extended timeout for gateway (35 seconds)")
                else:
                    # APs and unknown devices use standard timeout
                    timeout_seconds = 30
            else:
                timeout_seconds = 30

            # Wait for ARP results via WebSocket
            arp_result = websocket_manager.wait_for_command_result(session_id, timeout_seconds=timeout_seconds)

            if debug_mode:
                print(f"[DEBUG] wait_for_command_result returned: {arp_result is not None}")
                if arp_result:
                    print(f"[DEBUG] Result keys: {list(arp_result.keys())}")

            if arp_result:
                print("\n" + "=" * 60)
                print("ARP TABLE RESULTS:")
                print("=" * 60)

                # Add device-specific context
                if device_info:
                    device_type = device_info.get("type", "unknown")
                    device_model = device_info.get("model", "unknown")
                    device_name = device_info.get("name", "Unknown Device")

                    print(f"Device: {device_name} ({device_type.upper()}: {device_model})")

                    if device_type == "switch":
                        print("Note: Switch ARP data may show forwarding table or limited ARP information")
                    elif device_type == "gateway":
                        print("Note: Gateway ARP data may include routing information")
                    elif device_type == "ap":
                        print("Note: Access Point ARP data shows client connectivity information")

                    print("-" * 60)

                # Display raw output if available
                raw_output = arp_result.get("raw", "")
                if raw_output:
                    # Parse and display gateway data in table format if it's JSON
                    if device_info and device_info.get("type") == "gateway" and raw_output.strip().startswith("{"):
                        try:
                            # json is already imported globally
                            gateway_data = json.loads(raw_output)

                            if gateway_data.get("status") == "SUCCESS" and "rows" in gateway_data:
                                print("PARSED ARP TABLE:")
                                print("-" * 40)

                                # Get column headers
                                columns = gateway_data.get("columns", [])
                                if columns:
                                    # Create header row
                                    column_headers = [
                                        col.get("display_name", col.get("id", "Unknown")) for col in columns
                                    ]

                                    # Calculate column widths
                                    rows = gateway_data.get("rows", [])
                                    col_widths = []
                                    for idx, header in enumerate(column_headers):
                                        max_width = len(header)
                                        for row in rows:
                                            col_id = columns[idx].get("id", "")
                                            cell_value = str(row.get(col_id, ""))
                                            max_width = max(max_width, len(cell_value))
                                        col_widths.append(min(max_width + 2, 20))  # Cap at 20 chars

                                    # Print header
                                    header_line = " | ".join(
                                        header.ljust(col_widths[idx]) for idx, header in enumerate(column_headers)
                                    )
                                    print(header_line)
                                    print("-" * len(header_line))

                                    # Print data rows
                                    for row in rows:
                                        row_values = []
                                        for idx, col in enumerate(columns):
                                            col_id = col.get("id", "")
                                            cell_value = str(row.get(col_id, ""))
                                            # Truncate if too long
                                            if len(cell_value) > col_widths[idx] - 2:
                                                cell_value = cell_value[: col_widths[idx] - 5] + "..."
                                            row_values.append(cell_value.ljust(col_widths[idx]))
                                        print(" | ".join(row_values))

                                    print(f"\nTotal ARP Entries: {len(rows)}")

                                    # Also show raw for reference if debug mode
                                    if debug_mode:
                                        print("\nRAW JSON OUTPUT (Debug):")
                                        print("-" * 40)
                                        print(raw_output)
                                else:
                                    print("No column information available in gateway response")
                                    print("RAW OUTPUT:")
                                    print("-" * 40)
                                    print(raw_output)
                            else:
                                print("Gateway response format not recognized")
                                print("RAW OUTPUT:")
                                print("-" * 40)
                                print(raw_output)

                        except json.JSONDecodeError as json_error:
                            if debug_mode:
                                print(f"[DEBUG] Failed to parse gateway JSON: {json_error}")
                            print("Failed to parse gateway JSON output")
                            print("RAW OUTPUT:")
                            print("-" * 40)
                            print(raw_output)
                    else:
                        # For APs and other devices, show raw output
                        print("RAW OUTPUT:")
                        print("-" * 40)
                        print(raw_output)

                # Display parsed output if available
                parsed_output = arp_result.get("Output", "")
                if parsed_output and parsed_output != raw_output:
                    print("\nPARSED OUTPUT:")
                    print("-" * 40)
                    print(parsed_output)

                if not raw_output and not parsed_output:
                    print("No output data received")
                    if device_info and device_info.get("type") == "switch":
                        print("\nTroubleshooting for switches:")
                        print("-> Try using SSH-based commands instead")
                        print("-> Some switches require specific ARP command syntax")
                        print("-> WebSocket API may have limited switch support")

                print("=" * 60)

                # Log the successful operation with device context
                device_context = f"device {device_id}"
                if device_info:
                    device_context = f"{device_info.get('type', 'unknown')} {device_info.get('name', device_id[:8])}"
                logging.info(f"WebSocket ARP completed successfully for {device_context}")

            else:
                print("! Timeout waiting for ARP results")

                # Provide device-specific troubleshooting advice
                if device_info:
                    device_type = device_info.get("type", "unknown")
                    device_model = device_info.get("model", "unknown")

                    if device_type == "switch":
                        print(f"\nSwitch troubleshooting ({device_model}):")
                        print("-> Switches often have limited WebSocket ARP support")
                        print("-> Try using SSH-based 'show arp' commands instead")
                        print("-> Some switch models require specific command syntax")
                        print("-> Consider using Menu option for SSH device commands")
                    elif device_type == "gateway":
                        print(f"\nGateway troubleshooting ({device_model}):")
                        print("-> Try increasing timeout or checking network connectivity")
                        print("-> Gateway may require different ARP command format")
                    else:
                        print(f"\nGeneral troubleshooting ({device_type}):")
                        print("-> Check device connectivity and WebSocket support")
                        print("-> Some devices may require SSH-based commands")

                logging.warning("WebSocket ARP operation timed out")

        except Exception as arp_error:
            error_message = f"WebSocket ARP operation failed: {arp_error}"
            print(f"! {error_message}")
            logging.error(error_message)
            logging.debug("EXIT: arp_device_websocket - error")

        finally:
            # Always cleanup WebSocket connection
            try:
                websocket_manager_local = locals().get("websocket_manager")
                if websocket_manager_local is not None:
                    websocket_manager_local.disconnect()
                    print("-> WebSocket connection closed")
            except Exception as cleanup_error:
                logging.warning(f"WebSocket cleanup error: {cleanup_error}")

            logging.debug("EXIT: arp_device_websocket")

    @staticmethod
    def service_ping_device():  # type: ignore[no-untyped-def]
        """
        Execute service ping command on SSR gateway devices via WebSocket.
        Service ping allows ping packets to follow the same path as specific services.

        Follows the documented Mist API pattern for service ping commands:
        1. Subscribe to WebSocket channel
        2. POST service ping command with service-specific parameters
        3. Receive results via WebSocket stream with session-based demultiplexing

        SECURITY: Uses authenticated WebSocket connection with session-based
        command demultiplexing for concurrent command safety.
        """
        manager = ServicePingManager()  # type: ignore[no-untyped-call]
        return manager.execute()


class WebSocketCommands:
    """
    WebSocket Commands Class for Mist API device operations.

    This class organizes all WebSocket-based device command functions following
    the agents guide requirement that "All features, or helpers need to live
    under the appropriately titled/named 'Class's for code clarity and organization."

    All methods are static since they don't require instance state and can be
    called directly from menu actions.

    SECURITY: All methods use authenticated WebSocket connections with session-based
    command demultiplexing for concurrent command safety.
    """

    @staticmethod
    def show_mac_table():  # type: ignore[no-untyped-def]  # noqa: C901, PLR0912, PLR0915
        """
        Execute show MAC table command on a switch device via WebSocket.

        MAC tables are a Layer 2 switching feature and are only meaningful on switches.
        Routers/gateways operate at Layer 3 and typically don't maintain MAC tables.

        Follows the documented Mist API pattern:
        1. Connect to WebSocket
        2. Subscribe to device command channel
        3. Issue POST show_mac_table command
        4. Await results via WebSocket stream

        SECURITY: Uses authenticated WebSocket connection with session-based
        command demultiplexing for concurrent command safety.
        """
        logging.info("Menu #5: Starting WebSocket show MAC table operation")
        # Check for debug mode from command line arguments
        debug_mode = "--debug" in sys.argv or "-d" in sys.argv

        if debug_mode:
            logging.getLogger().setLevel(logging.DEBUG)
            print("[DEBUG] DEBUG MODE ENABLED")

        logging.debug("ENTER: show_mac_table_websocket")

        try:
            # Interactive site selection
            site_id = PromptUtils.select_site_id_from_csv()
            if not site_id:
                print("! No site selected. Operation cancelled.")
                return

            if debug_mode:
                print(f"[DEBUG] Selected site_id = {site_id}")

            # Get device selection - MAC table is a Layer 2 switching feature
            print("-> MAC table is available on switches (Layer 2 devices)")
            print("-> Routers/gateways operate at Layer 3 and typically don't maintain MAC tables")
            print("-> APs forward wireless traffic but don't maintain traditional MAC tables")
            device_id = PromptUtils.select_device_id_from_inventory(site_id, device_type="switch")
            if not device_id:
                print("! No switch device selected. MAC table command requires Layer 2 switching devices.")
                print("! Only switches maintain MAC address learning tables for Ethernet forwarding.")
                return

            if debug_mode:
                print(f"[DEBUG] Selected device_id = {device_id}")

            print(f"\n-> Executing show MAC table on device {device_id}...")
            print("-> Establishing WebSocket connection...")

            # Initialize WebSocket manager
            websocket_manager = WebSocketManager(apisession)

            if debug_mode:
                print("[DEBUG] WebSocketManager initialized")

            # Connect to WebSocket
            if not websocket_manager.connect():
                print("! Failed to establish WebSocket connection")
                return

            if debug_mode:
                print("[DEBUG] WebSocket connection established")

            # Subscribe to device command channel
            command_channel = f"/sites/{site_id}/devices/{device_id}/cmd"
            if not websocket_manager.subscribe_to_channel(command_channel):
                print("! Failed to subscribe to device command channel")
                websocket_manager.disconnect()
                return

            if debug_mode:
                print(f"[DEBUG] Subscribed to channel: {command_channel}")

            print("-> WebSocket connected and subscribed")

            # Wait a moment for subscription to be established
            time.sleep(1)

            # Issue show MAC table command via REST API
            mac_table_payload: dict[str, Any] = {}  # show_mac_table typically doesn't require additional parameters

            print("-> Issuing show MAC table command...")
            logging.debug(f"MAC table payload: {mac_table_payload}")

            if debug_mode:
                print(f"[DEBUG] MAC table payload = {mac_table_payload}")

            # Get authentication details for direct HTTP request
            mist_host = getattr(apisession, "host", None) or os.getenv("MIST_HOST")
            mist_apitoken = getattr(apisession, "apitoken", None) or os.getenv("MIST_APITOKEN")

            if not mist_host or not mist_apitoken:
                print("! Mist host or API token not found in session or environment")
                websocket_manager.disconnect()
                return

            if debug_mode:
                print(f"[DEBUG] mist_host = {mist_host}")
                print(f"[DEBUG] API token length = {len(mist_apitoken) if mist_apitoken else 0}")

            # Make direct POST request to trigger show MAC table
            mac_table_url = f"https://{mist_host}/api/v1/sites/{site_id}/devices/{device_id}/show_mac_table"
            headers = {"Authorization": f"Token {mist_apitoken}", "Content-Type": "application/json"}

            if debug_mode:
                print(f"[DEBUG] POST URL = {mac_table_url}")
                print("[DEBUG] Headers = {'Authorization': 'Token [REDACTED]', 'Content-Type': 'application/json'}")

            mac_table_response = requests.post(mac_table_url, headers=headers, json=mac_table_payload, timeout=30)

            if debug_mode:
                print(f"[DEBUG] HTTP Response Status = {mac_table_response.status_code}")
                print(f"[DEBUG] HTTP Response Body = {mac_table_response.text}")

            if mac_table_response.status_code != 200:
                print(f"! Failed to issue show MAC table command: {mac_table_response.status_code}")
                print(f"! Response: {mac_table_response.text}")
                websocket_manager.disconnect()
                return

            # Extract session ID from response
            response_data = mac_table_response.json()
            session_id = response_data.get("session")
            if not session_id:
                print("! No session ID returned from show MAC table command")
                websocket_manager.disconnect()
                return

            print(f"-> Show MAC table command issued (session: {session_id[:8]}...)")
            print("-> Waiting for MAC table results...")

            if debug_mode:
                print(f"[DEBUG] Full session ID = {session_id}")
                print("[DEBUG] Starting to wait for WebSocket results...")

            # Wait for MAC table results via WebSocket (longer timeout for potentially large tables)
            mac_table_result = websocket_manager.wait_for_command_result(session_id, timeout_seconds=60)

            if debug_mode:
                print(f"[DEBUG] wait_for_command_result returned: {mac_table_result is not None}")
                if mac_table_result:
                    print(f"[DEBUG] Result keys: {list(mac_table_result.keys())}")

            if mac_table_result:
                print("\n" + "=" * 60)
                print("MAC TABLE RESULTS:")
                print("=" * 60)

                # Display raw output (this is where MAC table results come according to documentation)
                raw_output = mac_table_result.get("raw", "")
                if raw_output:
                    print("RAW OUTPUT:")
                    print("-" * 40)
                    print(raw_output)

                # Display any other output fields that might be present
                output_fields = mac_table_result.get("Output", "")
                if output_fields and output_fields != raw_output:
                    print("\nOTHER OUTPUT:")
                    print("-" * 40)
                    print(output_fields)

                # Show all available fields for debugging
                available_fields = [key for key in mac_table_result.keys() if key not in ["raw", "Output", "session"]]
                if available_fields:
                    print(f"\nOTHER AVAILABLE FIELDS: {available_fields}")
                    for field in available_fields:
                        field_value = mac_table_result.get(field)
                        if field_value:
                            print(f"{field}: {field_value}")

                if not raw_output and not output_fields:
                    print("No output data received")
                    print(f"Available result keys: {list(mac_table_result.keys())}")

                print("=" * 60)

                # Log the successful operation
                logging.info("WebSocket show MAC table completed successfully")

            else:
                print("! Timeout waiting for MAC table results")
                print("! This may indicate:")
                print("  - The device doesn't support MAC table commands (common for routers/Layer 3 devices)")
                print("  - The device is busy or not responding")
                print("  - Network connectivity issues")
                print("! Note: MAC tables are primarily a Layer 2 (switch) feature")
                logging.warning("WebSocket show MAC table operation timed out")

                if debug_mode:
                    print("[DEBUG] Checking WebSocket manager state...")
                    print(f"[DEBUG] Connected = {websocket_manager.connected}")
                    print(f"[DEBUG] Subscribed channels = {websocket_manager.subscribed_channels}")
                    with websocket_manager.results_lock:
                        print(f"[DEBUG] Pending results = {list(websocket_manager.command_results.keys())}")

        except Exception as mac_table_error:
            error_message = f"WebSocket show MAC table operation failed: {mac_table_error}"
            print(f"! {error_message}")
            logging.error(error_message)

            if debug_mode:
                print("[DEBUG] Exception details:")
                import traceback

                traceback.print_exc()

            logging.debug("EXIT: show_mac_table_websocket - error")

        finally:
            # Always cleanup WebSocket connection
            try:
                websocket_manager_local = locals().get("websocket_manager")
                if websocket_manager_local is not None:
                    websocket_manager_local.disconnect()
                    print("-> WebSocket connection closed")

                    if debug_mode:
                        print("[DEBUG] WebSocket cleanup completed")
            except Exception as cleanup_error:
                logging.warning(f"WebSocket cleanup error: {cleanup_error}")

            logging.debug("EXIT: show_mac_table_websocket")

    @staticmethod
    def show_forwarding_table():  # type: ignore[no-untyped-def]
        """
        Execute show forwarding table command on a gateway/SSR device via WebSocket.

        Displays Layer 3 routing table information for gateway/SSR devices.
        This is a routing table diagnostic command specifically for devices that
        perform Layer 3 forwarding functions.

        SECURITY: Uses authenticated WebSocket connection with session-based
        command demultiplexing for concurrent command safety.
        """
        logging.info("Menu #6: Starting WebSocket show forwarding table operation")
        return RoutingUtils.execute_show_forwarding_table()  # type: ignore[no-untyped-call]

    @staticmethod
    def show_routing_table():  # type: ignore[no-untyped-def]
        """
        Execute show route command on switches, routers, and SSR devices via WebSocket.

        Displays routing table information (RIB - Routing Information Base) for network devices.
        This shows the routing protocol information maintained by routing protocols like BGP, OSPF,
        static routes, etc. Different from forwarding table (FIB) which shows actual forwarding entries.

        Supported on:
        - Switches with Layer 3 capabilities
        - SRX routers
        - SSR gateways
        - Other routing-capable devices

        SECURITY: Uses authenticated WebSocket connection with session-based
        command demultiplexing for concurrent command safety.
        """
        logging.info("Menu #7: Starting WebSocket show routing table operation")
        return RoutingUtils.execute_show_routing_table()  # type: ignore[no-untyped-call]

    @staticmethod
    def show_ssr_routes():  # type: ignore[no-untyped-def]
        """
        Execute SSR/SRX routing table command using dedicated API function.

        Uses the dedicated mistapi.api.v1.sites.devices.showSiteSsrAndSrxRoutes function
        which provides structured routing table queries specifically optimized for
        SSR and SRX devices with proper parameter validation and device-specific formatting.

        This is the preferred method for SSR/SRX routing table queries as it provides:
        - Structured parameter input (protocol, neighbor, prefix, vrf, node, route direction)
        - Device-specific optimization for SSR/SRX platforms
        - Proper BGP neighbor route analysis (received/advertised)
        - VRF-aware routing table queries
        - HA cluster node selection for multi-node deployments

        Supported devices:
        - SSR gateways (128T Session Smart Routers)
        - SRX routers (Juniper SRX series)

        SECURITY: Uses authenticated API session with proper parameter validation
        and device capability checking for safe routing table operations.
        """
        logging.info("Menu #8: Starting SSR/SRX routing table query")
        return RoutingUtils.execute_show_ssr_routes()  # type: ignore[no-untyped-call]


class ServicePingManager:
    """
    Manager class for SSR Service Ping operations via WebSocket.

    Handles tenant/service discovery, user interaction, and WebSocket execution
    for service-specific ping operations on SSR gateways.
    """

    # Default values for service ping operations
    DEFAULT_HOST = "8.8.8.8"
    DEFAULT_COUNT = 4
    DEFAULT_SIZE = 56
    MIN_SIZE = 56
    MAX_SIZE = 65535
    DEFAULT_TENANT = "testing-tools"
    DEFAULT_SERVICE = "web-session"

    def __init__(self):  # type: ignore[no-untyped-def]
        """Initialize ServicePingManager with debug mode detection."""
        self.debug_mode = is_debug_mode()  # type: ignore[no-untyped-call]
        self.site_id: str | None = None
        self.device_id: str | None = None
        self.device_info: dict | None = None  # type: ignore[type-arg]
        self.websocket_manager: WebSocketManager | None = None

        # Tenant sources (in precedence order)
        self.org_tenants: list[str] = []
        self.site_tenants: list[str] = []
        self.policy_tenants: list[str] = []
        self.template_tenants: list[str] = []
        self.device_tenants: list[str] = []

        # Service sources
        self.org_services: list[dict] = []  # type: ignore[type-arg]
        self.org_service_names: list[str] = []
        self.device_services: list[str] = []

    def _debug_print(self, message: str) -> None:
        """Print debug message if debug mode is enabled."""
        if self.debug_mode:
            print(f"[DEBUG] {message}")

    def _select_site_and_device(self) -> bool:
        """
        Prompt user to select site and gateway device.

        Returns:
            bool: True if selection successful, False otherwise
        """
        self.site_id = PromptUtils.select_site_id_from_csv()
        if not self.site_id:
            print("! No site selected. Operation cancelled.")
            return False

        self._debug_print(f"Selected site_id = {self.site_id}")

        self.device_id = PromptUtils.select_device_id_from_inventory(self.site_id, device_type="gateway")
        if not self.device_id:
            print("! No gateway devices found or selected. Service Ping requires an SSR gateway.")
            return False

        self._debug_print(f"Selected device_id = {self.device_id}")
        return True

    def _fetch_device_info(self) -> bool:
        """
        Fetch and validate device information.

        Returns:
            bool: True if device is valid for service ping, False otherwise
        """
        try:
            rawdata = mistapi.api.v1.sites.devices.listSiteDevices(apisession, self.site_id, type="gateway").data
            self.device_info = next((device for device in rawdata if device.get("id") == self.device_id), None)
        except Exception as error:
            logging.warning(f"Could not retrieve device details: {error}")
            self._debug_print(f"Device details error: {error}")
            return self._confirm_unknown_device()

        if not self.device_info:
            return self._confirm_unknown_device()

        return self._validate_device_type()

    def _validate_device_type(self) -> bool:
        """Validate device type and prompt for confirmation if not a gateway."""
        if self.device_info is None:
            return self._confirm_unknown_device()

        device_type = self.device_info.get("type", "unknown")
        device_model = self.device_info.get("model", "unknown")

        self._debug_print(f"Device type: {device_type}, model: {device_model}")

        if device_type == "gateway":
            print(f"!? SSR Gateway detected (Model: {device_model})")
            print("   -> Service Ping allows ping packets to follow service-specific paths")
            return True

        # Non-gateway device - warn and confirm
        type_messages = {"ap": "Access Point", "switch": "Switch"}
        device_label = type_messages.get(device_type, "Unknown device type")
        print(f"!? WARNING: {device_label} detected (Model: {device_model})")
        print("   -> Service Ping is designed for SSR gateways")

        return self._confirm_proceed()

    def _confirm_unknown_device(self) -> bool:
        """Confirm proceeding with unknown device type."""
        print("!? Cannot determine device type - proceeding with caution")
        print("   -> Service Ping is designed for SSR gateways")
        return self._confirm_proceed()

    def _confirm_proceed(self) -> bool:
        """Prompt user to confirm proceeding with non-optimal device."""
        choice = input("   -> Continue anyway? (y/N): ").strip().lower()
        if choice != "y":
            print("Operation cancelled.")
            return False
        return True

    def _fetch_all_tenants(self) -> None:
        """Fetch tenants from all sources."""
        print("\n-> Fetching organization tenants...")
        self._fetch_org_tenants()

        print("-> Fetching site tenants...")
        self._fetch_site_tenants()

        print("-> Fetching service policy tenants...")
        self._fetch_policy_tenants()

        print("-> Fetching gateway template tenants...")
        self._fetch_template_tenants()

    def _fetch_org_tenants(self) -> None:
        """Fetch organization-level tenants."""
        tenants = APITenantFetchUtils.organization_tenants()
        if tenants:
            self.org_tenants = tenants
            print(f"   -> Found {len(self.org_tenants)} organization-level tenants")
            self._debug_print(f"Organization tenants: {self.org_tenants}")
        else:
            print("   -> No organization-level tenants found")

    def _fetch_site_tenants(self) -> None:
        """Fetch site-level tenants."""
        if self.site_id is None:
            return
        tenants = APITenantFetchUtils.site_tenants(self.site_id)
        if tenants:
            self.site_tenants = tenants
            print(f"   -> Found {len(self.site_tenants)} site-level tenants")
            self._debug_print(f"Site tenants: {self.site_tenants}")
        else:
            print("   -> No site-level tenants found")

    def _fetch_policy_tenants(self) -> None:
        """Fetch service policy tenants."""
        tenants = APITenantFetchUtils.service_policy_tenants(self.site_id)  # type: ignore[no-untyped-call]
        if tenants:
            self.policy_tenants = tenants
            print(f"   -> Found {len(self.policy_tenants)} service policy tenants")
            self._debug_print(f"Service policy tenants: {self.policy_tenants}")
        else:
            print("   -> No service policy tenants found")

    def _fetch_template_tenants(self) -> None:
        """Fetch gateway template tenants."""
        tenants = APITenantFetchUtils.gateway_template_tenants(self.site_id)  # type: ignore[no-untyped-call]
        if tenants:
            self.template_tenants = tenants
            print(f"   -> Found {len(self.template_tenants)} gateway template tenants")
            self._debug_print(f"Gateway template tenants: {self.template_tenants}")
        else:
            print("   -> No gateway template tenants found")

    def _fetch_all_services(self) -> None:
        """Fetch services from organization and device configuration."""
        print("\n-> Fetching organization services...")
        self._fetch_org_services()

        print("-> Fetching device configuration for additional options...")
        self._fetch_device_config()

    def _fetch_org_services(self) -> None:
        """Fetch organization-level services."""
        services = APIFetchUtils.organization_services()
        if services:
            self.org_services = services
            self.org_service_names = [svc["name"] for svc in services if svc.get("name")]
            print(f"   -> Found {len(self.org_service_names)} organization-level services")
            self._debug_print(f"Organization services: {self.org_service_names}")
        else:
            print("   -> No organization-level services found")

    def _fetch_device_config(self) -> None:
        """Fetch device configuration for tenants and services."""
        try:
            config_response = mistapi.api.v1.sites.devices.getSiteDevice(apisession, self.site_id, self.device_id)
            device_config = getattr(config_response, "data", {})
            self._debug_print(f"Device config keys: {list(device_config.keys())}")

            self._extract_from_device_config(device_config)
            self._extract_from_device_stats()

        except Exception as error:
            logging.warning(f"Could not fetch device configuration: {error}")
            self._debug_print(f"Config error: {error}")
            print("!? Cannot retrieve device configuration")

    def _extract_from_device_config(self, config: dict) -> None:  # type: ignore[type-arg]
        """Extract tenants and services from device configuration."""
        tenants_set: set = set()  # type: ignore[type-arg]
        services_set: set = set()  # type: ignore[type-arg]

        # Extract from service_policies
        for policy in config.get("service_policies", []):
            if isinstance(policy, dict):
                if tenant := policy.get("tenant"):
                    tenants_set.add(tenant)
                self._extract_services_from_policy(policy, services_set)

        # Extract from routing_instances
        for instance in config.get("routing_instances", []):
            if isinstance(instance, dict):
                if name := instance.get("name"):
                    if not name.startswith("_"):
                        tenants_set.add(name)

        # Extract from router configuration
        self._extract_from_router_config(config.get("router", {}), tenants_set, services_set)

        # Filter and store results
        self.device_tenants = sorted([t for t in tenants_set if t and not t.startswith("_")])
        self.device_services = sorted([s for s in services_set if s and not s.startswith("_")])

        self._report_device_config_results()

    def _extract_services_from_policy(self, policy: dict, services_set: set) -> None:  # type: ignore[type-arg]
        """Extract services from a service policy."""
        services = policy.get("services", [])
        if not isinstance(services, list):
            return

        for service_item in services:
            if isinstance(service_item, dict):
                if name := service_item.get("name"):
                    services_set.add(name)
            elif isinstance(service_item, str):
                services_set.add(service_item)

    def _extract_from_router_config(self, router: dict, tenants: set, services: set) -> None:  # type: ignore[type-arg]
        """Extract tenants and services from router configuration."""
        if not isinstance(router, dict):
            return

        for tenant_item in router.get("tenants", []):
            if isinstance(tenant_item, dict):
                if name := tenant_item.get("name"):
                    tenants.add(name)

        for service_item in router.get("services", []):
            if isinstance(service_item, dict):
                if name := service_item.get("name"):
                    services.add(name)

    def _extract_from_device_stats(self) -> None:
        """Extract additional services from device stats."""
        try:
            stats_response = mistapi.api.v1.sites.stats.getSiteDeviceStats(apisession, self.site_id, self.device_id)
            stats_data = getattr(stats_response, "data", {})
            self._debug_print(f"Stats keys: {list(stats_data.keys())}")

            for service_stat in stats_data.get("service_stat", []):
                if isinstance(service_stat, dict):
                    if name := service_stat.get("name"):
                        if not name.startswith("_") and name not in self.device_services:
                            self.device_services.append(name)
                            self.device_services.sort()

        except Exception as error:
            self._debug_print(f"Could not fetch stats: {error}")

    def _report_device_config_results(self) -> None:
        """Report device configuration extraction results."""
        self._debug_print(f"Found tenants from device: {self.device_tenants}")
        self._debug_print(f"Found services from device: {self.device_services}")

        if self.device_tenants:
            print(f"   -> Found {len(self.device_tenants)} tenants from device configuration")
        else:
            print("   -> No tenants found in device configuration")

        if self.device_services:
            print(f"   -> Found {len(self.device_services)} additional services from device configuration")
        else:
            print("   -> No additional services found in device configuration")

    def _build_combined_tenants(self) -> list[str]:
        """Combine tenants from all sources with deduplication."""
        combined = list(self.org_tenants)

        # Add from each source if not already present
        for source in [self.site_tenants, self.policy_tenants, self.template_tenants, self.device_tenants]:
            for tenant in source:
                if tenant not in combined:
                    combined.append(tenant)

        # Ensure default tenant exists
        if self.DEFAULT_TENANT not in combined:
            combined.append(self.DEFAULT_TENANT)
            self._debug_print(f"Added default tenant: {self.DEFAULT_TENANT}")

        self._debug_print(f"Combined tenant list: {combined}")
        return combined

    def _build_combined_services(self) -> list[str]:
        """Combine services from all sources with deduplication."""
        combined = list(self.org_service_names)

        for service in self.device_services:
            if service not in combined:
                combined.append(service)

        # Ensure default service exists
        if self.DEFAULT_SERVICE not in combined:
            combined.append(self.DEFAULT_SERVICE)
            self._debug_print(f"Added default service: {self.DEFAULT_SERVICE}")

        self._debug_print(f"Combined service list: {combined}")
        return combined

    def _prompt_for_tenant(self, available_tenants: list[str]) -> str | None:
        """Prompt user to select a tenant."""
        if not available_tenants:
            return self._prompt_manual_tenant()

        print("\nAvailable Tenants:")
        self._display_tenant_categories(available_tenants)

        default_index = None
        if self.DEFAULT_TENANT in available_tenants:
            default_index = available_tenants.index(self.DEFAULT_TENANT)

        print(f"  [{len(available_tenants)}] Skip tenant selection")

        return self._get_tenant_selection(available_tenants, default_index)

    def _display_tenant_categories(self, all_tenants: list[str]) -> None:  # noqa: C901
        """Display tenants organized by source category."""
        index = 0

        # Organization tenants
        if self.org_tenants:
            print(f"  Organization Tenants ({len(self.org_tenants)}):")
            for name in self.org_tenants:
                print(f"    [{index}] {name} (org networks)")
                index += 1

        # Site-only tenants
        site_only = [t for t in self.site_tenants if t not in self.org_tenants]
        if site_only:
            print(f"  Site Tenants ({len(site_only)}):")
            for name in site_only:
                print(f"    [{index}] {name} (site networks)")
                index += 1

        # Policy-only tenants
        policy_only = [t for t in self.policy_tenants if t not in self.org_tenants and t not in self.site_tenants]
        if policy_only:
            print(f"  Service Policy Tenants ({len(policy_only)}):")
            for name in policy_only:
                print(f"    [{index}] {name} (service policies)")
                index += 1

        # Template-only tenants
        template_only = [
            t
            for t in self.template_tenants
            if t not in self.org_tenants and t not in self.site_tenants and t not in self.policy_tenants
        ]
        if template_only:
            print(f"  Gateway Template Tenants ({len(template_only)}):")
            for name in template_only:
                print(f"    [{index}] {name} (gateway templates)")
                index += 1

        # Device-only tenants
        device_only = [
            t
            for t in self.device_tenants
            if t not in self.org_tenants
            and t not in self.site_tenants
            and t not in self.policy_tenants
            and t not in self.template_tenants
        ]
        if device_only:
            print(f"  Device Configuration Tenants ({len(device_only)}):")
            for name in device_only:
                print(f"    [{index}] {name} (device config)")
                index += 1

        # Remaining (defaults)
        remaining = [
            t
            for t in all_tenants
            if t not in self.org_tenants
            and t not in self.site_tenants
            and t not in self.policy_tenants
            and t not in self.template_tenants
            and t not in self.device_tenants
        ]
        if remaining:
            print(f"  Additional Tenants ({len(remaining)}):")
            for name in remaining:
                print(f"    [{index}] {name} (default/custom)")
                index += 1

    def _get_tenant_selection(self, tenants: list[str], default_index: int | None) -> str | None:
        """Get tenant selection from user input."""
        while True:
            try:
                prompt = f"\nSelect tenant index (0-{len(tenants)})"
                if default_index is not None:
                    prompt += f" [default: {default_index} ({self.DEFAULT_TENANT})]: "
                else:
                    prompt += " [default: skip]: "

                selection = input(prompt).strip()

                if not selection:
                    if default_index is not None:
                        tenant = tenants[default_index]
                        print(f"!? Using default tenant: {tenant}")
                        return tenant
                    return None

                idx = int(selection)
                if idx == len(tenants):
                    print("!? Skipping tenant selection")
                    return None

                if 0 <= idx < len(tenants):
                    tenant = tenants[idx]
                    self._print_tenant_source(tenant)
                    return tenant

                print(f"Please enter a number between 0 and {len(tenants)}")

            except ValueError:
                print("Please enter a valid number")
            except KeyboardInterrupt:
                print("\nOperation cancelled")
                raise

    def _print_tenant_source(self, tenant: str) -> None:
        """Print the source of a selected tenant."""
        if tenant in self.org_tenants:
            print(f"!? Selected organization tenant: {tenant}")
        elif tenant in self.site_tenants:
            print(f"!? Selected site tenant: {tenant}")
        elif tenant in self.policy_tenants:
            print(f"!? Selected service policy tenant: {tenant}")
        elif tenant in self.template_tenants:
            print(f"!? Selected gateway template tenant: {tenant}")
        elif tenant in self.device_tenants:
            print(f"!? Selected device configuration tenant: {tenant}")
        else:
            print(f"!? Selected default/custom tenant: {tenant}")

    def _prompt_manual_tenant(self) -> str | None:
        """Prompt for manual tenant entry when none available."""
        print("\n-> No tenants found in any configuration source")
        manual = input("-> Enter tenant name manually (or press Enter to skip): ").strip()
        if manual:
            print(f"!? Manual tenant: {manual}")
            return manual
        print("-> Proceeding without tenant (may cause service ping to fail)")
        return None

    def _prompt_for_service(self, available_services: list[str]) -> str:
        """Prompt user to select a service."""
        if not available_services:
            return self._prompt_required_service()

        print("\nAvailable Services:")
        self._display_service_categories(available_services)

        default_index = None
        if self.DEFAULT_SERVICE in available_services:
            default_index = available_services.index(self.DEFAULT_SERVICE)

        print(f"  [{len(available_services)}] Enter custom service name")

        return self._get_service_selection(available_services, default_index)

    def _display_service_categories(self, all_services: list[str]) -> None:
        """Display services organized by source category."""
        index = 0

        # Organization services
        if self.org_service_names:
            print(f"  Organization Services ({len(self.org_service_names)}):")
            for name in self.org_service_names:
                details = next((s for s in self.org_services if s["name"] == name), {})
                svc_type = details.get("type", "custom")
                desc = details.get("description", "")
                if desc:
                    print(f"    [{index}] {name} ({svc_type}) - {desc}")
                else:
                    print(f"    [{index}] {name} ({svc_type})")
                index += 1

        # Device-only services
        device_only = [s for s in self.device_services if s not in self.org_service_names]
        if device_only:
            print(f"  Device Configuration Services ({len(device_only)}):")
            for name in device_only:
                print(f"    [{index}] {name} (device config)")
                index += 1

        # Remaining (defaults)
        remaining = [s for s in all_services if s not in self.org_service_names and s not in self.device_services]
        if remaining:
            print(f"  Additional Services ({len(remaining)}):")
            for name in remaining:
                print(f"    [{index}] {name} (default/custom)")
                index += 1

    def _get_service_selection(self, services: list[str], default_index: int | None) -> str:
        """Get service selection from user input."""
        while True:
            try:
                prompt = f"\nSelect service index (0-{len(services)}) or enter custom"
                if default_index is not None:
                    prompt += f" [default: {default_index} ({self.DEFAULT_SERVICE})]: "
                else:
                    prompt += ": "

                selection = input(prompt).strip()

                if not selection:
                    if default_index is not None:
                        service = services[default_index]
                        print(f"!? Using default service: {service}")
                        return service
                    print("Please enter a service name or select from the list")
                    continue

                try:
                    idx = int(selection)
                    if idx == len(services):
                        return self._prompt_custom_service()

                    if 0 <= idx < len(services):
                        service = services[idx]
                        self._print_service_source(service)
                        return service

                    print(f"Please enter a number between 0 and {len(services)}")

                except ValueError:
                    # Treat as custom service name
                    print(f"!? Custom service: {selection}")
                    return selection

            except KeyboardInterrupt:
                print("\nOperation cancelled")
                raise

    def _print_service_source(self, service: str) -> None:
        """Print the source of a selected service with details if available."""
        if service in self.org_service_names:
            print(f"!? Selected organization service: {service}")
            details = next((s for s in self.org_services if s["name"] == service), {})
            if details.get("description"):
                print(f"  Description: {details['description']}")
            if details.get("type"):
                print(f"  Type: {details['type']}")
        elif service in self.device_services:
            print(f"!? Selected device configuration service: {service}")
        else:
            print(f"!? Selected default/custom service: {service}")

    def _prompt_custom_service(self) -> str:
        """Prompt for custom service name."""
        while True:
            service = input("Enter custom service name: ").strip()
            if service:
                print(f"!? Custom service: {service}")
                return service
            print("Service name cannot be empty")

    def _prompt_required_service(self) -> str:
        """Prompt for required service when none available."""
        print("\n-> No services found in organization or device configuration")
        while True:
            service = input("Enter service name: ").strip()
            if service:
                print(f"!? Custom service: {service}")
                return service
            print("Service is required. Please enter a service name.")

    def _prompt_for_ping_parameters(self) -> dict:  # type: ignore[type-arg]
        """Prompt for ping parameters and build payload."""
        # Host
        host = input("\nEnter target host/IP to ping [default: 8.8.8.8]: ").strip()
        if not host:
            host = self.DEFAULT_HOST
            print(f"!? Using default destination: {host}")

        # Count
        count = self._prompt_for_count()

        # Size
        size = self._prompt_for_size()

        # HA Node
        node = self._prompt_for_node()

        return {"host": host, "count": count, "size": size, "node": node}

    def _prompt_for_count(self) -> int:
        """Prompt for ping count."""
        count_input = input("Enter ping count [default: 4]: ").strip()
        try:
            count = int(count_input) if count_input else self.DEFAULT_COUNT
            return max(1, count)
        except ValueError:
            return self.DEFAULT_COUNT

    def _prompt_for_size(self) -> int:
        """Prompt for packet size."""
        size_input = input("Enter packet size in bytes [default: 56]: ").strip()
        try:
            size = int(size_input) if size_input else self.DEFAULT_SIZE
            return max(self.MIN_SIZE, min(size, self.MAX_SIZE))
        except ValueError:
            return self.DEFAULT_SIZE

    def _prompt_for_node(self) -> str | None:
        """Prompt for HA node selection."""
        node_input = input("Enter HA node (node0/node1) [optional]: ").strip().lower()
        return node_input if node_input in ["node0", "node1"] else None

    def _build_payload(self, service: str, tenant: str | None, params: dict) -> dict:  # type: ignore[type-arg]
        """Build service ping API payload."""
        payload = {"host": params["host"], "service": service, "count": params["count"], "size": params["size"]}

        if tenant:
            payload["tenant"] = tenant
        if params["node"]:
            payload["node"] = params["node"]

        return payload

    def _display_configuration(self, payload: dict) -> None:  # type: ignore[type-arg]
        """Display service ping configuration summary."""
        print("\n" + "-" * 50)
        print("Service Ping Configuration:")
        print(f"  Host: {payload['host']}")
        print(f"  Service: {payload['service']}")
        print(f"  Count: {payload['count']}")
        print(f"  Size: {payload['size']} bytes")
        if payload.get("tenant"):
            print(f"  Tenant: {payload['tenant']}")
        if payload.get("node"):
            print(f"  HA Node: {payload['node']}")
        print("-" * 50)

        self._debug_validate_service(payload["service"])

    def _debug_validate_service(self, service: str) -> None:
        """Log debug information about service validation."""
        if not self.debug_mode:
            return

        known_services = ["web-session", "LANS", "RBO_SSH"]
        if service in known_services:
            print(f"[DEBUG] Using known valid service: {service}")
        else:
            print(f"[DEBUG] Using custom service: {service} (may not exist on device)")

    def _setup_websocket(self) -> bool:
        """Initialize and connect WebSocket."""
        self.websocket_manager = WebSocketManager(apisession)

        if not self.websocket_manager.connect():
            print("! Failed to establish WebSocket connection")
            return False

        self._debug_print("WebSocket connection established")

        command_channel = f"/sites/{self.site_id}/devices/{self.device_id}/cmd"
        if not self.websocket_manager.subscribe_to_channel(command_channel):
            print("! Failed to subscribe to device command channel")
            return False

        self._debug_print(f"Subscribed to channel: {command_channel}")
        print("-> WebSocket connected and subscribed")

        print("-> Waiting for subscription confirmation...")
        if not self.websocket_manager.wait_for_subscription_confirmation(command_channel, timeout_seconds=15):  # type: ignore[no-untyped-call]
            print("! Subscription confirmation not received within timeout")
            print("! Proceeding anyway, but results may not be received")
        else:
            print("-> Subscription confirmed")

        return True

    def _execute_service_ping(self, payload: dict) -> str | None:  # type: ignore[type-arg]
        """Execute service ping API call and return session ID."""
        print("-> Issuing Service Ping command...")

        self._debug_print(f"Service ping payload being sent: {payload}")
        logging.info(f"Sending service ping via mistapi to device: {self.device_id}")
        logging.info(f"Service ping payload: {payload}")

        try:
            response = mistapi.api.v1.sites.devices.servicePingFromSsr(
                apisession, self.site_id, self.device_id, payload
            )

            logging.info(f"Service ping mistapi response status: {response.status_code}")
            logging.info(f"Service ping mistapi response data: {response.data}")

            self._debug_print(f"mistapi Response Status = {response.status_code}")
            self._debug_print(f"mistapi Response Data = {response.data}")

            if response.status_code != 200:
                print(f"Failed to issue Service Ping command. Status {response.status_code}: {response.data}")
                logging.error(f"Service ping failed - status {response.status_code}: {response.data}")
                return None

            session_id = response.data.get("session", "")
            if session_id:
                short_id = session_id[:8] + "..." if len(session_id) > 8 else session_id
                print(f"-> Service Ping command issued (session: {short_id})")
                self._debug_print(f"Full session ID: {session_id}")
            else:
                print("-> Service Ping command issued (no session ID returned)")

            return session_id or None

        except Exception as error:
            print(f"Error issuing Service Ping command via mistapi: {error}")
            logging.error(f"Service ping error: {error}")
            self._debug_print(f"mistapi exception details: {type(error).__name__}: {error}")
            return None

    def _wait_for_results(self, session_id: str) -> dict | None:  # type: ignore[type-arg]
        """Wait for WebSocket results."""
        print("-> Waiting for Service Ping results...")

        self._debug_print(f"Full session ID = {session_id}")
        self._debug_print("Starting to wait for WebSocket results...")

        if self.websocket_manager is None:
            return None

        # Determine timeout based on device type
        if self.device_info and self.device_info.get("type") == "gateway":
            timeout_seconds = 45
            activity_timeout = 5
            print("   -> Using extended timeout for SSR gateway (45s total, 5s activity)")
        else:
            timeout_seconds = 30
            activity_timeout = 3

        result = self.websocket_manager.wait_for_command_result(
            session_id, timeout_seconds=timeout_seconds, activity_timeout_seconds=activity_timeout
        )

        self._debug_print(f"wait_for_command_result returned: {result is not None}")
        if result:
            self._debug_print(f"Result keys: {list(result.keys())}")

        return result

    def _display_results(self, result: dict | None, payload: dict) -> None:  # type: ignore[type-arg]
        """Display service ping results."""
        if result:
            self._display_success_results(result, payload)
        else:
            self._display_timeout_results(payload)

    def _display_success_results(self, result: dict, payload: dict) -> None:  # type: ignore[type-arg]
        """Display successful ping results."""
        print("\n" + "=" * 60)
        print("SERVICE PING RESULTS:")
        print("=" * 60)

        if self.device_info is not None:
            self._display_device_context(payload)

        raw_output = result.get("raw", "")
        if raw_output:
            print("PING OUTPUT:")
            print("-" * 40)
            print(raw_output)

        parsed_output = result.get("Output", "")
        if parsed_output and parsed_output != raw_output:
            print("\nPARSED OUTPUT:")
            print("-" * 40)
            print(parsed_output)

        if not raw_output and not parsed_output:
            print("No output data received")
            if self.device_info and self.device_info.get("type") != "gateway":
                self._display_non_gateway_troubleshooting()

        print("=" * 60)
        self._log_success(payload)

    def _display_device_context(self, payload: dict) -> None:  # type: ignore[type-arg]
        """Display device context in results."""
        if self.device_info is None:
            return
        device_type = self.device_info.get("type", "unknown")
        device_model = self.device_info.get("model", "unknown")
        device_name = self.device_info.get("name", "Unknown Device")

        print(f"Device: {device_name} ({device_type.upper()}: {device_model})")
        print(f"Service: {payload['service']} -> Host: {payload['host']}")

        if device_type == "gateway":
            print("Note: Service-specific routing path used for ping packets")
        else:
            print("Note: Device may not fully support service ping functionality")

        print("-" * 60)

    def _display_non_gateway_troubleshooting(self) -> None:
        """Display troubleshooting for non-gateway devices."""
        print("\nTroubleshooting for non-gateway devices:")
        print("-> Service Ping is designed specifically for SSR gateways")
        print("-> Try using regular ping (Menu 87) instead")
        print("-> Verify device supports service ping functionality")

    def _log_success(self, payload: dict) -> None:  # type: ignore[type-arg]
        """Log successful operation."""
        if self.device_info:
            name = self.device_info.get("name", "Unknown Device")
            dtype = self.device_info.get("type", "unknown")
            logging.info(
                f"Service ping completed for {name} ({dtype}) - Service: {payload['service']}, Host: {payload['host']}"
            )
        else:
            logging.info(
                f"Service ping completed for device {self.device_id} - Service: {payload['service']}, Host: {payload['host']}"  # noqa: E501
            )

    def _display_timeout_results(self, payload: dict) -> None:  # type: ignore[type-arg]
        """Display timeout/no results message with troubleshooting."""
        print("\nNo Service Ping results received within timeout period.")

        if not self.device_info:
            logging.warning(f"Service ping timeout - no results received for device {self.device_id}")
            return

        device_type = self.device_info.get("type", "unknown")
        device_name = self.device_info.get("name", "Unknown Device")
        print(f"Device: {device_name} ({device_type})")

        troubleshooting = {
            "gateway": [
                "Verify service name is valid for this SSR",
                "Check if host is reachable through the specified service",
                "Confirm SSR routing configuration for the service",
                "Try with a different service name",
            ],
            "switch": [
                "Switches typically do not support service ping",
                "Try using regular ping (Menu 87) for basic connectivity",
                "Service ping is an SSR-specific feature",
            ],
            "ap": [
                "Access Points do not support service ping",
                "Try using regular ping (Menu 87) for basic connectivity",
                "Service ping is an SSR-specific feature",
            ],
        }

        tips = troubleshooting.get(
            device_type,
            ["Service ping is designed for SSR gateways", "Try using regular ping (Menu 87) for basic connectivity"],
        )

        if device_type == "gateway":
            print("\nTroubleshooting for SSR gateways:")
        else:
            print(f"\nNote: {tips[0]}")
            tips = tips[1:]

        for tip in tips:
            print(f"-> {tip}")

        logging.warning(f"Service ping timeout - no results received for device {self.device_id}")

    def _cleanup(self) -> None:
        """Clean up WebSocket connection."""
        try:
            if self.websocket_manager is not None:
                self.websocket_manager.disconnect()
                print("-> WebSocket connection closed")
        except Exception as error:
            logging.warning(f"WebSocket cleanup error: {error}")

    def execute(self) -> None:
        """
        Main execution method for service ping operation.

        Orchestrates the complete service ping workflow:
        1. Site and device selection
        2. Device validation
        3. Tenant and service discovery
        4. User configuration prompts
        5. WebSocket setup and execution
        6. Results display and cleanup
        """
        logging.debug("ENTER: ServicePingManager.execute")

        if self.debug_mode:
            print("[DEBUG] Starting Service Ping via WebSocket operation...")
            print(f"[DEBUG] Command line args: {sys.argv}")

        try:
            # Phase 1: Selection and validation
            if not self._select_site_and_device():
                return

            if not self._fetch_device_info():
                return

            # Phase 2: Discovery
            self._fetch_all_tenants()
            self._fetch_all_services()

            # Phase 3: Build combined lists
            all_tenants = self._build_combined_tenants()
            all_services = self._build_combined_services()

            # Phase 4: User configuration
            print("\n" + "=" * 50)
            print("SERVICE PING CONFIGURATION")
            print("=" * 50)

            tenant = self._prompt_for_tenant(all_tenants)
            service = self._prompt_for_service(all_services)
            params = self._prompt_for_ping_parameters()

            # Phase 5: Build and display payload
            payload = self._build_payload(service, tenant, params)
            self._display_configuration(payload)

            # Phase 6: Execute
            print(f"\n-> Executing Service Ping on device {self.device_id}...")

            if not self._setup_websocket():
                return

            session_id = self._execute_service_ping(payload)
            if not session_id:
                print("! No session ID received - cannot wait for results")
                return

            # Phase 7: Wait and display results
            result = self._wait_for_results(session_id)
            self._display_results(result, payload)

        except KeyboardInterrupt:
            print("\nOperation cancelled by user")
            logging.info("Service ping operation cancelled by user")

        except Exception as error:
            print(f"Error during Service Ping operation: {error}")
            logging.error(f"Service ping error: {error}")

        finally:
            self._cleanup()
            logging.debug("EXIT: ServicePingManager.execute")


